# you cannot change your parents once you're born
ALLOW_FOSTER_PARENTING = False


def multiline_iterable(
    iterable,
    separator=", ",
    max_line_length=100,
    indent="",
    extra_indent="  ",
    linebreak="",
    prefix="[",
    suffix="]",
    prefix_suffix_lines=True,
):
    """
    Generate the lines of a written representation of a list-like object.

    :param iterable: the iterable to be translated to text
    :param separator: separator that connects elements, e.g. ", "
    :param max_line_length: maximum line length before line break comes
    :param indent: indentation to be included in every line
    :param extra_indent: extra indent after the first line
    :param linebreak: a linebreak character, required by some languages
    :param prefix: before list starts
    :param suffix: after list ends
    :param head_tail_lines: head_tail_lines

    """

    # prepare the data, copy, make list, ...
    listlike = list(iterable)
    not_empty = len(listlike) > 0

    # the first element is treated differently, as it does not require a separator in front
    is_first = True

    # if prefix and suffix are in separate lines, start here
    if prefix_suffix_lines:
        # yield extra head line, then prepare next. No size check here!
        line = indent + prefix
        fill = max(0, (max_line_length - len(line) - len(linebreak))) * " "
        if prefix:
            yield line + fill + linebreak
            line = indent + extra_indent
        else:
            line = indent
    else:
        # start with indented and headed line but don't yield yet
        line = indent + prefix

    # go through listlike
    while listlike:
        # pop first in list
        string = str(listlike.pop(0))

        # check if can be appended or new line required
        if (
            len(line + separator + string + separator + linebreak)
            <= max_line_length
        ):
            # can be appended: append (w/ or w/o separator)
            if is_first:
                line += string
                is_first = False
            else:
                line += separator + string
        else:
            # can not be appended. Append only separator, space-pad and yield
            line += separator
            fill = (max_line_length - len(line) - len(linebreak)) * " "
            yield line + fill + linebreak
            # and put in next line
            line = indent + extra_indent + string

    # if prefix and suffix are in separate lines, treat here
    if prefix_suffix_lines:
        # first, handle not yet yielded lines.
        if line and not_empty:
            # not empty check: empty list would get create an extra emtpy line only with indent!
            fill = (max_line_length - len(line) - len(linebreak)) * " "
            yield line + fill + linebreak
        if suffix:
            # extra suffix line
            yield indent + suffix
    else:
        # again, take care of leftover line, but attempt to append suffix.
        if len(line + suffix) <= max_line_length:
            yield line + suffix
        else:
            yield line + linebreak
            if suffix:
                yield indent + suffix


def multiline_text(
    large_text,
    max_line_length=80,
    indent="",
    apply_strip=True,
):
    """
    Create multiline text. Special wrapper call for multiline_iterator.


    """
    if apply_strip:
        large_text = large_text.strip()
    for section in large_text.split("\n"):
        if apply_strip:
            section = section.strip()
        words = list(section.split(" "))
        yield from multiline_iterable(
            words,
            separator=" ",
            max_line_length=max_line_length,
            indent=indent,
            extra_indent="",
            prefix="",
            suffix="",
            prefix_suffix_lines=False,
        )


class CodeContainer:
    """
    A Codecontainer is a fundamental building block in the code that is
    ultimately generated. This is the internal base class that includes
    anything that is not yet language specific.

    """

    _IND = "  "

    def __init__(self, signature: Any = None, parent=None, **params) -> None:
        # all content that may or may not be useful
        self._params = params

        # the call signature
        self._call_signature = signature

        # collect variables that are used here
        self._requirements: Set[LibRoutineVariable] = set()

        # content, divided in three sections, head, body, foot
        self._container_head: list[CodeContainer] = []
        self._container_body: list[CodeContainer] = []
        self._container_foot: list[CodeContainer] = []

        # parent link
        self._wr_parent: wrReferenceType[CodeContainer] | None = None
        self._set_parent(parent)  # manage parent reference, might be weak

        # indent body?
        self._body_indent = False

        # hierarchy level
        if self.parent is None:
            level = 0
        else:
            level = self.parent.level
        self._level = level

    @classmethod
    def container_from_instruction(
        cls,
        instruction: Instruction,
        builder,
        context: Tuple[int, InstructionEnvironment, Instruction | None],
        buildargs=None,
    ):
        """Generator! Request data from instruction, supplement with defaults if valid."""
        if buildargs is None:
            buildargs = {}
        (environment, level, parent) = context
        yield from cls(
            level=level,
            signature=builder.get_signature(
                instruction, environment, buildargs
            ),
            parent=parent,
            **instruction.to_dict(),
        ).complete(builder, environment, buildargs).representatives()

    def representatives(self):
        """yield the containers that represent self. Is self in many cases"""
        yield self

    def complete(self, builder, environment, buildargs, **kwargs):
        """complete the instruction from the builder in the proper environment"""
        print("Complete called")
        print(f"\tBuilder    : {builder}")
        print(f"\tEnvironment: {environment}")
        print(f"\tbuild args : {buildargs}")
        return self

    def _set_parent(self, parent):
        """private method to manage the parent reference"""
        if parent is None:
            self._wr_parent = None
        else:
            self._wr_parent = ref(parent)

    def _get_code_container_lines_head(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        if self._container_head is not None:
            for content in self._container_head:
                yield from content.get_codelines(indent=indent, **kwargs)

    def _get_code_container_lines_body(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        if self._container_body is not None:
            indent += 1 if self._body_indent else 0
            for content in self._container_body:
                yield from content.get_codelines(indent=indent, **kwargs)

    def _get_code_container_lines_foot(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        if self._container_foot is not None:
            for content in self._container_foot:
                yield from content.get_codelines(indent=indent, **kwargs)

    def get_codelines(
        self, indent: int = 0, **kwargs: Any
    ) -> Generator[str, None, None]:
        """get the codelines from the container"""
        yield from self._get_code_container_lines_head(indent, **kwargs)
        yield from self._get_code_container_lines_body(indent, **kwargs)
        yield from self._get_code_container_lines_foot(indent, **kwargs)

    @property
    def level(self):
        """access the level but prohibit setting it manually"""
        return self._level

    @property
    def parent(self) -> CodeContainer | None:
        """access the parent"""
        if self._wr_parent is None:
            return None
        if (parent := self._wr_parent()) is None:
            raise ValueError("Parent has been garbage collected")
        return parent

    @parent.setter
    def parent(self, parent: CodeContainer) -> None:
        """safe-set parent, IF ALLOWED"""
        if not ALLOW_FOSTER_PARENTING:
            raise RuntimeError("The Lord does not allow that!")
        if self._wr_parent is None:
            if isinstance(parent, CodeContainer):
                self._wr_parent = ref(parent)
        else:
            raise ValueError("Parent already set")

    @property
    def body(self):
        """iterate through body content only"""
        yield from self._container_body

    @property
    def head(self):
        """iterate through head content only"""
        yield from self._container_head

    @property
    def foot(self):
        """iterate through foot content only"""
        yield from self._container_foot

    @property
    def content(self):
        """iterate through foot content only"""
        yield from self.head
        yield from self.body
        yield from self.foot

    def update_requirements(
        self,
    ) -> Generator[LibRoutineVariable, None, None]:
        """iterate over all possible requirements. Eliminate duplicates"""
        known = set()
        for cont in self.content:
            for requirement in cont.update_requirements():
                if requirement not in known:
                    known.add(requirement)
                    yield requirement

    def reset_provided_requirements(self) -> None:
        """reset the provided requirements"""
        for content in self.content:
            content.reset_provided_requirements()

    def append_head(self, *containers: CodeContainer) -> None:
        """append at head"""
        for container in containers:
            self._container_head.append(container)

    def append_body(self, *containers: CodeContainer) -> None:
        """append at body"""
        for container in containers:
            self._container_body.append(container)

    def append_foot(self, *containers: CodeContainer) -> None:
        """append at foot"""
        for container in containers:
            self._container_foot.append(container)

    def requires(self, requirement: LibRoutineVariable) -> None:
        """add a requirement to the codeblock"""
        if not isinstance(requirement, LibRoutineVariable):
            raise TypeError("Dependencies must be LibRoutineVariables")
        self._requirements.add(requirement)

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        # if not overwritten, generic CodeContainers do not captere anything
        return False

    @classmethod
    def compatibility_check(cls, signature):
        """checks if anything speaks against using this container"""
        return True


class GroupContainer(CodeContainer):
    """
    A GroupContainer is made from a group instruction and potentially holds
    several other containers inside. The grouping might only be symbolically.
    Head and Foot are not occupyable by anything other than formal block
    delimiters and comments.
    """

    def __init__(self, content, signature=None, parent=None, **params):
        super().__init__(signature=signature, parent=parent, **params)
        self._content = content

    # should default to getting the content of body without any extras.

    def append(self, content):
        """append a container to the body"""
        self._container_body.append(content)
        content.parent = self


class EnclosingContainer(GroupContainer):
    """
    An Environment block. Opening and closing operators so pairs always match.
    Indent optional. Made for brackets, parenthesis, definitions, ...
    Brackets in brackets are treated, ignored or combined.
    As the group container requires, head and foot are defined by the Environment
    class and are not occupied
    """

    def __init__(
        self, content, environment, signature=None, parent=None, **params
    ):
        transformed_content = content.apply_environment(environment)
        super().__init__(
            transformed_content, signature=signature, parent=parent, **params
        )


class LoopContainer(EnclosingContainer):
    """
    A LoopContainer provides basic loop control capabilities. It can derive into
    different versions depending on the architecture.
    """


class DefinitionContainer(CodeContainer):
    """
    A code container that defines stuff and prevents them from getting passed
    on during requirement iterator. Supports a filtering function that decides
    on which type of requirements are implemented here or passed on.
    """

    def __init__(self, **params) -> None:
        super().__init__(**params)
        self._filter_func_customs: Set[Callable] = set()
        self._filter_func_captures: Set[str] = set()
        self._provide: Set[LibRoutineVariable] = set()

    def add_capture(self, capture: str | Callable) -> None:
        """add a type of requirement to capture"""
        if isinstance(capture, str):
            self._filter_func_captures.add(capture)
        elif callable(capture):
            self._filter_func_customs.add(capture)
        else:
            raise ValueError(
                f"Invalid filter arg {capture}. Must be str|callable."
            )

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        for func in self._filter_func_customs:
            if func(requirement):
                return True
        if requirement.vtype in self._filter_func_captures:
            return True
        return False

    def reset_provided_requirements(self):
        for content in self.content:
            content.reset_provided()
        self._provide = set()

    def update_requirements(
        self,
    ) -> Generator[LibRoutineVariable, None, None]:
        """As parent, but keep the requirements that the filter catches"""
        for requirement in super().update_requirements():
            if self.capture_check(requirement):
                self._provide.add(requirement)
            else:
                yield requirement


